import {normalizeSearch} from './library-tools.js';
export function documentPassages(pages){return pages.flatMap((page,index)=>(page.ocr?.text||'').split(/\n+|(?<=[.!؟])\s+/).map(text=>({page:index+1,pageId:page.id,text:text.trim()})).filter(p=>p.text.length>10));}
export function answerFromDocument(pages,question,limit=5){const terms=[...new Set(normalizeSearch(question).split(/\s+/).filter(t=>t.length>2&&!['ماهو','ماهي','ماذا','كيف','this','what','where','about','المستند','الوثيقة'].includes(t)))];if(!terms.length)return[];return documentPassages(pages).map(p=>({...p,score:terms.reduce((sum,term)=>sum+(normalizeSearch(p.text).includes(term)?1:0),0)})).filter(p=>p.score>0).sort((a,b)=>b.score-a.score||a.page-b.page).slice(0,limit);}
export function extractiveSummary(pages,limit=6){const passages=documentPassages(pages),chosen=[];const seen=new Set();for(const p of passages){const normalized=normalizeSearch(p.text);if(seen.has(normalized))continue;seen.add(normalized);chosen.push(p);if(chosen.length>=limit)break;}return chosen;}
export function simpleEquations(text){return String(text).split(/\n/).map(s=>s.trim()).filter(s=>s.length<220&&/[=+×÷√]/.test(s)&&/[0-9٠-٩a-zA-Z]/.test(s)).slice(0,40).map(s=>({text:s,latex:s.replace(/×/g,'\\times ').replace(/÷/g,'\\div ').replace(/√\(([^)]+)\)/g,'\\sqrt{$1}').replace(/\^\(([^)]+)\)/g,'^{$1}')}));}
